import{_ as a,o as s,c as n,ae as t}from"./chunks/framework.DQC_QtFV.js";const u=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"personal-bot","text":"A self-hosted personal assistant","tagline":"It runs on your own machine, keeps its memory in files you own, and answers in the chats you already use.","actions":[{"theme":"brand","text":"Quick start","link":"/en/guide/quick-start"},{"theme":"alt","text":"How it works","link":"/en/guide/how-it-works"}]},"features":[{"title":"Read","details":"Received messages come from a private, decrypted copy of the client's own database - real message ids, senders, mentions, quotes and images, without touching the client's process."},{"title":"Write","details":"Text, images, stickers, @mentions and quote replies go through the client's own send function, paced by one action queue with human-like jitter."},{"title":"Remember","details":"Notes the assistant writes itself are its only long-term memory; every turn and tool call lands in a searchable log."},{"title":"Come back later","details":"wait, wake words, scheduled tasks, and optional free turns - a turn of its own when nothing has happened for a while."},{"title":"Use tools","details":"Web search and page reading, a shell and files in a sandbox, skills and MCP servers - each function switched on or off in the panel."},{"title":"Panel","details":"Live view and login, conversations and policies, persona, memory, stickers, schedules, models, safety, workspace, advanced settings and logs - one page per topic."}]},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md","lastUpdated":1793164923000}`),i={name:"en/index.md"};function o(r,e,l,p,d,c){return s(),n("div",null,[...e[0]||(e[0]=[t(`<div class="warning custom-block"><p class="custom-block-title">Read this first</p><p>This project drives a third-party desktop client, which is outside that client&#39;s terms of service and can get an account restricted or lost. Use a secondary account, a residential connection and the default pacing. Private research project, provided as is, and all of the risk is yours. Read the <a href="./guide/disclaimer.html">disclaimer</a> before you run anything.</p></div><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>Four containers. One runs a chat client on a virtual display; the other three are the assistant, the panel you drive it from, and a sandbox the assistant&#39;s commands run in. One stack is one account.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────── one stack = one account ──────────────────────────┐</span></span>
<span class="line"><span>│                                                                                  │</span></span>
<span class="line"><span>│  chat client (official, unmodified, headless)                                    │</span></span>
<span class="line"><span>│    │ writes              ▲ sends              ▲ clicks 登录                       │</span></span>
<span class="line"><span>│    ▼                     │                    │                                  │</span></span>
<span class="line"><span>│  private decrypted copy ──▶ driver API (HTTP + WebSocket)                        │</span></span>
<span class="line"><span>│                              │                        │                          │</span></span>
<span class="line"><span>│                              ▼                        ▼                          │</span></span>
<span class="line"><span>│                          console :8080            bot :8766                      │</span></span>
<span class="line"><span>│                          (the panel,              (the agent, notes,             │</span></span>
<span class="line"><span>│                           the live view)           the send review)              │</span></span>
<span class="line"><span>│                                                      │                           │</span></span>
<span class="line"><span>│                                                      ▼                           │</span></span>
<span class="line"><span>│                                                  sandbox :8791                   │</span></span>
<span class="line"><span>│                                                  (every command, as an           │</span></span>
<span class="line"><span>│                                                   unprivileged user)             │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h2><ul><li><a href="./guide/quick-start.html">Quick start</a>: requirements, clone, <code>.env</code>, <code>docker compose up -d</code>.</li><li><a href="./guide/first-start.html">First start and QR login</a>: where QQ comes from, how the key is read, who scans the QR code.</li><li><a href="./guide/env.html">Environment variables</a>: what every variable in <code>.env</code> means.</li><li><a href="./guide/console/">Console</a>: every page of the panel, one page per topic.</li><li><a href="./guide/mcp.html">MCP client</a>: registering this assistant with an OAuth MCP server.</li></ul><h2 id="models-whatever-pi-supports" tabindex="-1">Models: whatever pi supports <a class="header-anchor" href="#models-whatever-pi-supports" aria-label="Permalink to &quot;Models: whatever pi supports&quot;">​</a></h2><p>The agent is built on <a href="https://pi.dev" target="_blank" rel="noreferrer">pi</a>, so every provider and model pi supports is available: log a provider in, or add a key, on the console&#39;s <a href="./guide/console/models.html">模型 page</a>. The model catalog is fetched at bot start and refreshed automatically once a day (neither when <code>PI_OFFLINE=1</code>), and can be refreshed on demand, so new models appear without a restart.</p><p>The full project write-up is the repository&#39;s <a href="https://github.com/4fuu/personal-bot" target="_blank" rel="noreferrer">README</a>; the context and memory mechanism is <a href="https://github.com/4fuu/personal-bot/blob/main/docs/how-it-works.md" target="_blank" rel="noreferrer">docs/how-it-works.md</a>.</p>`,9)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
